builder.Services.AddOutputCache(options =>
{
    options.AddBasePolicy(b => b.Expire(TimeSpan.FromSeconds(10)));
    options.AddPolicy("Catalog", b => b
        .Expire(TimeSpan.FromMinutes(5))
        .SetVaryByQuery("region", "page")
        .Tag("catalog"));
});
builder.Services.AddStackExchangeRedisOutputCache(/* redis options */);

var app = builder.Build();
app.UseOutputCache();
app.MapGet("/api/catalog", GetCatalog).CacheOutput("Catalog");

builder.Services.AddResponseCaching();
var app = builder.Build();
app.UseResponseCaching(); // after UseRouting, before endpoints

app.MapGet("/api/public/faq", async () => Results.Json(await _faq.GetAll()))
   .CacheOutput(p => p.Expire(TimeSpan.FromHours(1)).Tag("faq"));

// Controller: [ResponseCache(Duration = 120, Location = ResponseCacheLocation.Any)]

app.MapPut("/api/admin/catalog/{id}", async (int id, CatalogUpdate dto,
    ICatalogService svc, IOutputCacheStore cache) =>
{
    await svc.UpdateAsync(id, dto);
    await cache.EvictByTagAsync("catalog", CancellationToken.None);
    return Results.NoContent();
});

options.AddPolicy("UserOrders", b => b
    .Expire(TimeSpan.FromSeconds(30))
    .VaryByValue((context) => new KeyValuePair<string, string>(
        "user", context.User.FindFirstValue(ClaimTypes.NameIdentifier) ?? "anon"))
    .SetCacheKeyPrefix("orders"));
// Without VaryByValue user id, user A receives user B cached JSON — OWASP API1
